/* General Styles */
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
  display: flex;
}

.main-content {
  flex-grow: 1;
  padding: 20px;
}

/* Sidebar Styles */
.sidebar {
  width: 250px;
  background-color: #0044cc;
  color: white;
  padding-top: 20px;
}

.sidebar ul {
  list-style-type: none;
  padding: 0;
}

.sidebar ul li {
  position: relative;
}

.sidebar ul li a {
  display: block;
  padding: 10px 20px;
  text-decoration: none;
  color: white;
  font-size: 18px;
}

.sidebar ul li a:hover {
  background-color: #003399;
}

.sub-menu {
  display: none;
  list-style-type: none;
  padding: 0;
  background-color: #003399;
}

.sub-menu li a {
  padding: 10px 40px;
  font-size: 16px;
}

.sub-menu li a:hover {
  background-color: #002266;
}

.menu-item:hover .sub-menu {
  display: block;
}

